// phone-kit.js
// The same file sits in every class-11 phone folder. It does the plumbing every phone page
// needs, so sketch.js can be about the idea:
//   phoneSetup(room, extra)  joins the room as a phone. false means there is no server address
//   keepAwake()              asks the phone not to lock its screen. call it from the join tap
//   tiltNow()                { x, y } from -1 to 1. x is left to right, y is top to bottom
//   recentre()               counts the way you hold the phone right now as level
//   raiseNow()               0 when the phone lies flat, 1 when it is held upright
//   otherPhones()            the other phones in the room
//   checkMyName()            takes the lowest free number, or a new one if another phone has yours
//   footerLine()             one line about the connection, for the bottom of the screen
//   centreLines(str, y, w, h)  writes centred lines that wrap at w, the first one at y. h is the line height
//
// A laptop has no tilt sensor, so the mouse or the arrow keys stand in. Move the mouse
// across the page, or hold an arrow key.
//
// Call angleMode(DEGREES) in setup(), because the tilt comes in degrees.

const REACH = 30; // degrees of tilt that count as all the way, 1
const GREY_TEXT = '#9a9a9a';

let serverProblem = '';
let hasRealTilt = false;  // true once a phone has sent a real tilt reading
let neutralBeta = null;   // the front to back angle that counts as level
let mouseHasMoved = false;
let wakeLock = null;
let screenAwake = false;
let wantAwake = false;

// a name and a colour this phone keeps, so it is the same one each time it joins
function remembered(key, make) {
  try {
    let value = localStorage.getItem(key);
    if (!value) {
      value = String(make());
      localStorage.setItem(key, value);
    }
    return value;
  } catch (e) {
    return String(make());
  }
}
// each phone is a number, Phone 1, Phone 2 and so on: the lowest number no other phone in the room has.
// the phone keeps it, so it gets the same number back when it rejoins, if that number is still free
let myNumber = Number(remembered('class12Number', function () {
  return 0;   // 0 is no number yet. checkMyName() gives one once the phone is in the room
}));
let myName = myNumber > 0 ? 'Phone ' + myNumber : 'Phone';
let myHue = Number(remembered('class11Hue', function () {
  return Math.floor(Math.random() * 360);
}));

window.addEventListener('deviceorientation', function (e) {
  if (e.beta !== null) {
    hasRealTilt = true;
  }
});
window.addEventListener('mousemove', function () {
  mouseHasMoved = true;
});

// join the room as a phone. the address the projector's code holds carries the server and the room
function phoneSetup(room, extra) {
  textFont('system-ui');
  const fromUrl = new URLSearchParams(location.search).get('shareHost');
  const host = fromUrl || window.CLASS_SHARE_HOST || '';
  if (!host || host.indexOf('REPLACE-ME') >= 0) {
    serverProblem = 'This page has no server address. Scan the code on the big screen.';
    return false;
  }
  const me = Object.assign({ role: 'phone', name: myName, hue: myHue }, extra || {});
  return shareSetup({ host: host, room: room, me: me });
}

// ask the phone not to lock. a phone that locks leaves the room
async function keepAwake() {
  wantAwake = true;
  if (!('wakeLock' in navigator)) {
    return;
  }
  if (wakeLock && !wakeLock.released) {
    return;
  }
  try {
    wakeLock = await navigator.wakeLock.request('screen');
    screenAwake = true;
    wakeLock.addEventListener('release', function () {
      screenAwake = false;
    });
  } catch (e) {
    screenAwake = false;
  }
}
// a wake lock ends when the page is hidden. ask again when it comes back
document.addEventListener('visibilitychange', function () {
  if (document.visibilityState === 'visible' && wantAwake) {
    keepAwake();
  }
});

function recentre() {
  neutralBeta = null;
}

function tiltNow() {
  if (hasRealTilt) {
    if (neutralBeta === null) {
      neutralBeta = rotationX;
    }
    return {
      x: constrain(rotationY / REACH, -1, 1),
      y: constrain((rotationX - neutralBeta) / REACH, -1, 1)
    };
  }
  return laptopTilt();
}

// 0 when the phone lies flat, 1 when it is held upright
function raiseNow() {
  if (hasRealTilt) {
    return constrain(map(rotationX, 15, 75, 0, 1), 0, 1);
  }
  if (isMobile) {
    return 0; // a phone with no tilt readings stays quiet
  }
  const t = laptopTilt();
  return constrain(map(t.y, 1, -1, 0, 1), 0, 1);
}

// the mouse stands in for tilt on a laptop. the arrow keys win while they are held
function laptopTilt() {
  if (isMobile) {
    return { x: 0, y: 0 }; // a touch is not a mouse
  }
  let x = 0;
  let y = 0;
  if (mouseHasMoved) {
    x = constrain(map(mouseX, 0, width, -1, 1), -1, 1);
    y = constrain(map(mouseY, 0, height, -1, 1), -1, 1);
  }
  if (keyIsDown(LEFT_ARROW)) {
    x = -1;
  }
  if (keyIsDown(RIGHT_ARROW)) {
    x = 1;
  }
  if (keyIsDown(UP_ARROW)) {
    y = -1;
  }
  if (keyIsDown(DOWN_ARROW)) {
    y = 1;
  }
  return { x: x, y: y };
}

function otherPhones() {
  return guests.filter(function (g) {
    return g.role === 'phone';
  });
}

// two phones with one number are hard to tell apart. the phone that joined later picks again.
// the room gives every phone an id, so 'later' is the larger id, and only one of the two moves
function checkMyName() {
  if (!shareConnected) {
    return;
  }
  const others = otherPhones();
  const clash = others.some(function (g) {
    return g.name === me.name && String(g.id) < String(shareClientId);
  });
  if (myNumber > 0 && !clash) {
    return;
  }
  const taken = others.map(function (g) {
    return g.name;
  });
  let n = 1;
  while (taken.indexOf('Phone ' + n) >= 0) {
    n++;
  }
  myNumber = n;
  myName = 'Phone ' + n;
  me.name = myName;
  try {
    localStorage.setItem('class12Number', String(n));
  } catch (e) { /* the number just will not be kept */ }
}
// phones that join at the same moment can pick the same number, so look again every second
setInterval(checkMyName, 1000);

function footerLine() {
  if (serverProblem) {
    return serverProblem;
  }
  let line = 'Connecting';
  if (shareConnected) {
    line = 'Connected';
  } else if (shareStatus === 'error') {
    line = 'Cannot reach the server. Trying again';
  }
  if (wantAwake) {
    line += screenAwake ? '. Screen stays on' : '. Keep your screen on';
  }
  return line;
}

// centred text that wraps. the text size and colour must be set first.
// it draws lines of up to w pixels across the middle of the screen and returns how many
function centreLines(str, y, w, lineH) {
  textAlign(CENTER, BASELINE);
  const rows = String(str).split('\n');
  let drawn = 0;
  for (let r = 0; r < rows.length; r++) {
    const words = rows[r].split(' ');
    let line = '';
    for (let i = 0; i < words.length; i++) {
      const next = line ? line + ' ' + words[i] : words[i];
      if (line && textWidth(next) > w) {
        text(line, width / 2, y + drawn * lineH);
        drawn += 1;
        line = words[i];
      } else {
        line = next;
      }
    }
    text(line, width / 2, y + drawn * lineH);
    drawn += 1;
  }
  return drawn;
}

// 02 Chord: Phone
// p5.sound and Share. Your phone plays one note of a chord. The big screen gives it to you.
// Raise your phone and the note gets louder. Lay it flat and it goes quiet. Every phone
// in the room plays at once, so the room is the instrument.
//
// The rule: Share keeps only the last thing written, so this phone keeps its own volume in me
// and the projector adds them up.
//
// Try this:
//   Raise your phone, then lay it flat.
//   Find the other phones on your note. Raise them all together.
//   The projector can change the chord. Your note changes and the number stays yours.
//   On a laptop, move the mouse up and down, or use the up and down arrow keys.
//
// Key data:
//   shared.parts[shareClientId]  the note this phone plays. 0 is the lowest note
//   shared.chord                 { name, names, hz } the chord, written by the projector
//   me.vol                       this phone's volume, from 0 to 1, about ten times a second

const ROOM = 'chord';

// the feel of the piece. change these before you change anything else.
let waveType = 'triangle'; // 'sine' is purer. 'triangle' carries better on a phone speaker
let loudest = 0.35;        // the loudest this phone gets, from 0 to 1. a room full of phones adds up
let sendEvery = 100;       // milliseconds between volume updates

let osc;                   // the oscillator. it plays this phone's note
let joined = false;
let serverOk = false;
let lastSend = 0;
let playing = 0;           // the volume now, from 0 to 1
let pitch = 0;             // the pitch now, in hertz
let k = 1;                 // one design unit for this screen
let noteColors = ['#ffc800', '#3ddcff', '#ff6b9a', '#7cff8a'];

function setup() {
  createCanvas(windowWidth, windowHeight);
  lockGestures();
  angleMode(DEGREES);

  // it runs all the time, silent. the tilt turns it up
  osc = new p5.Oscillator(261.63, waveType);
  osc.amp(0);

  serverOk = phoneSetup(ROOM, { vol: 0 });
  if (serverOk) {
    // one tap turns on tilt and sound. userSetupComplete() runs after it
    enablePermissionsTap(['gyro', 'sound'], 'Tap to join the chord');
  }
}

function userSetupComplete() {
  joined = true;
  osc.start();        // after the sound tap, so it does not click
  keepAwake();        // a phone that locks leaves the room, and goes quiet
  shareConnect();
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

function shareReady() {
  checkMyName();
}

// the note the projector has given this phone, or nothing yet
function myNote() {
  const parts = shared.parts;
  const chord = shared.chord;
  if (!joined || !parts || !chord || parts[shareClientId] === undefined) {
    return null;
  }
  const i = parts[shareClientId];
  return { index: i, name: chord.names[i], hz: chord.hz[i], chord: chord.name };
}

function draw() {
  k = min(width / 390, height / 700);
  const note = myNote();

  // 1. read the tilt. 2. send it as the volume. 3. play the note at that volume.
  const raise = raiseNow();
  if (joined && shareConnected && millis() - lastSend >= sendEvery) {
    me.vol = round(raise * 20) / 20;    // steps of 0.05, so a phone held still sends nothing
    lastSend = millis();
  }
  let target = 0;
  if (note && shareConnected) {
    target = raise;
    if (note.hz !== pitch) {
      osc.freq(note.hz, 0.08);
      pitch = note.hz;
    }
  }
  if (abs(target - playing) > 0.01) {
    osc.amp(target * loudest, 0.1);
    playing = target;
  }

  // the screen glows in the colour of the note, as loud as the note
  const base = color(20);
  let glow = base;
  if (note) {
    glow = lerpColor(base, color(noteColors[note.index % 4]), playing * 0.45);
  }
  background(glow);

  drawNote(note, raise);
  drawFooter(note);
}

function drawNote(note, raise) {
  noStroke();
  fill(255);
  textStyle(BOLD);
  textSize(34 * k);
  if (!serverOk) {
    textSize(26 * k);
    centreLines(serverProblem, height * 0.2, width * 0.85, 34 * k);
    textStyle(NORMAL);
    return;
  }
  if (!joined || !shareConnected) {
    centreLines('02 Chord', height * 0.12, width * 0.9, 40 * k);
    textStyle(NORMAL);
    return;
  }
  if (!note) {
    centreLines('Waiting for a note', height * 0.12, width * 0.9, 40 * k);
    textStyle(NORMAL);
    fill('#9a9a9a');
    textSize(22 * k);
    centreLines('The big screen gives each phone one note.', height * 0.2, width * 0.8, 30 * k);
    return;
  }

  // your note, as big as the screen allows
  centreLines('Your note', height * 0.12, width * 0.9, 40 * k);
  fill(noteColors[note.index % 4]);
  textSize(min(width * 0.5, height * 0.3));
  centreLines(note.name, height * 0.42, width, 10);
  textStyle(NORMAL);

  fill('#cfcfcf');
  textSize(24 * k);
  let same = 0;
  for (let i = 0; i < guests.length; i++) {
    if (guests[i].role === 'phone' && shared.parts[guests[i].id] === note.index) {
      same += 1;
    }
  }
  let line = note.chord + '. ';
  if (same === 0) {
    line += 'You are the only one on this note.';
  } else if (same === 1) {
    line += '1 other phone plays it too.';
  } else {
    line += same + ' other phones play it too.';
  }
  centreLines(line, height * 0.5, width * 0.85, 32 * k);

  // how loud you are now
  const meterW = width * 0.7;
  const meterY = height * 0.62;
  fill(40);
  rect(width / 2 - meterW / 2, meterY, meterW, 22 * k);
  fill(noteColors[note.index % 4]);
  rect(width / 2 - meterW / 2, meterY, meterW * raise, 22 * k);
}

function drawFooter(note) {
  noStroke();
  fill('#9a9a9a');
  textSize(20 * k);
  if (joined && note) {
    const how = hasRealTilt ? 'Raise your phone to play louder.\nLay it flat to go quiet.' : 'Move the mouse up to play louder.\nMove it down to go quiet.';
    centreLines(how, height * 0.72, width * 0.86, 28 * k);
  }
  textSize(17 * k);
  centreLines(footerLine(), height - 40 * k, width * 0.9, 24 * k);
  if (joined) {
    centreLines('No sound? Check your phone is not on silent.', height - 70 * k, width * 0.9, 24 * k);
  }
}
